package dev.aegis.review.application;

import dev.aegis.identity.application.api.MemberDirectory; import dev.aegis.notifications.application.api.NoticeDraft; import dev.aegis.notifications.application.api.PublishNotice;
import dev.aegis.review.application.api.ReviewInbox; import dev.aegis.review.application.ports.ReviewActionDispatcher; import dev.aegis.review.application.ports.ReviewProducer;
import dev.aegis.review.domain.*; import dev.aegis.shared.*; import java.nio.charset.StandardCharsets; import java.time.Clock; import java.util.*;

/** Reconciles persisted workflow cards with authoritative producer views and delegates every business action. */
public class ReviewService implements ReviewInbox, dev.aegis.review.application.api.ReviewPortability {
 private final ReviewRepository repository; private final List<ReviewProducer> producers; private final ReviewActionDispatcher actions; private final HouseholdAccess access; private final MemberDirectory members; private final PublishNotice notices; private final Clock clock;
 public ReviewService(ReviewRepository repository,List<ReviewProducer> producers,ReviewActionDispatcher actions,HouseholdAccess access,MemberDirectory members,PublishNotice notices,Clock clock){this.repository=repository;this.producers=List.copyOf(producers);this.actions=actions;this.access=access;this.members=members;this.notices=notices;this.clock=clock;}
 @Override public List<Item> list(Actor actor,String status,String category){access.requireMember(actor); reconcile(actor); return repository.findAll().stream().filter(i->status==null||status.isBlank()||i.status().name().equals(status)).filter(i->category==null||category.isBlank()||i.category().equals(category)).sorted(Comparator.comparing(ReviewItem::createdAt).reversed()).map(ReviewService::view).toList();}
 @Override public Item dismiss(Actor actor,UUID id,long expectedVersion){access.requireMember(actor);ReviewItem i=load(id);check(i,expectedVersion);long old=i.version();i.decide(ReviewStatus.DISMISSED,actor.memberId(),clock.instant());repository.update(i,old);return view(i);}
 @Override public Item act(Actor actor,UUID id,String action,long expectedVersion){access.requireMember(actor);ReviewItem i=load(id);check(i,expectedVersion);if(!i.actions().contains(action))throw new InvalidInputException("review.action.invalid","Action is not available for this review item");actions.execute(actor,i,action);long old=i.version();i.decide(ReviewStatus.RESOLVED,actor.memberId(),clock.instant());repository.update(i,old);return view(i);}
 private void reconcile(Actor actor){Set<String> current=new HashSet<>();for(ReviewProducer p:producers){for(var c:p.findCurrent(actor)){current.add(c.fingerprint());if(repository.findByFingerprint(c.fingerprint()).isEmpty()){ReviewItem i=ReviewItem.create(UUID.nameUUIDFromBytes(c.fingerprint().getBytes(StandardCharsets.UTF_8)),c,clock.instant());repository.insert(i);for(var m:members.listMembers(actor)){if(m.active())notices.publish(new NoticeDraft(m.id(),"REVIEW_ITEM", "review:"+i.id(),Map.of("titleKey",i.titleKey()),"REVIEW",i.id().toString()));}}}}for(ReviewItem i:repository.findAll()){if(i.status()==ReviewStatus.OPEN&&!current.contains(i.fingerprint())){long old=i.version();i.decide(ReviewStatus.SUPERSEDED,actor.memberId(),clock.instant());repository.update(i,old);}}}
 private ReviewItem load(UUID id){return repository.find(id).orElseThrow(()->new NotFoundException("reviewItem",id.toString()));} private static void check(ReviewItem i,long v){if(i.version()!=v)throw new StaleVersionException("reviewItem",i.id().toString(),v,i.version());if(i.status()!=ReviewStatus.OPEN)throw new InvalidInputException("review.item.closed","Review item is no longer open");}
 private static Item view(ReviewItem i){return new Item(i.id(),i.sourceKind(),i.sourceId(),i.sourceVersion(),i.category(),i.reason(),i.priority(),i.titleKey(),i.params(),i.linkType(),i.linkId(),i.actions(),i.status().name(),i.createdAt(),i.updatedAt(),i.version());}
 @Override public List<dev.aegis.review.application.api.ReviewPortability.Record> exportAll(Actor actor){access.requireMember(actor);return repository.findAll().stream().map(i->new dev.aegis.review.application.api.ReviewPortability.Record(i.id(),i.fingerprint(),i.producer(),i.sourceKind(),i.sourceId(),i.sourceVersion(),i.category(),i.reason(),i.priority(),i.titleKey(),i.params(),i.linkType(),i.linkId(),i.actions(),i.status().name(),i.createdAt(),i.updatedAt(),i.version(),i.decidedBy()==null?null:i.decidedBy().toString(),i.decidedAt())).toList();}
 @Override public void importAll(Actor actor,List<dev.aegis.review.application.api.ReviewPortability.Record> records){access.requireMember(actor);for(var r:records){if(repository.find(r.id()).isEmpty()&&repository.findByFingerprint(r.fingerprint()).isEmpty())repository.insert(ReviewItem.rehydrate(r.id(),r.fingerprint(),r.producer(),r.sourceKind(),r.sourceId(),r.sourceVersion(),r.category(),r.reason(),r.priority(),r.titleKey(),r.params(),r.linkType(),r.linkId(),r.actions(),ReviewStatus.valueOf(r.status()),r.createdAt(),r.updatedAt(),r.version(),r.decidedBy()==null?null:MemberId.of(r.decidedBy()),r.decidedAt()));}}
}
